import React from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";

// Styled components for the popup
const Overlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const PopupContainer = styled.div`
  background-color: white;
  border-radius: 8px;
  padding: 20px;
  width: 400px;
  text-align: center;
  box-shadow: 0px 10px 30px rgba(0, 0, 0, 0.1);
`;

const Title = styled.h2`
  font-size: 24px;
  color: #333;
  margin-bottom: 20px;
`;

const Message = styled.p`
  font-size: 18px;
  color: #555;
  margin-bottom: 20px;
`;

const ButtonWrapper = styled.div`
  display: flex;
  justify-content: space-between;
`;

const Button = styled.button`
  padding: 10px 20px;
  font-size: 16px;
  cursor: pointer;
  border: none;
  border-radius: 6px;
  transition: background-color 0.3s;

  &:first-child {
    background-color: #f44336;
    color: white;

    &:hover {
      background-color: #d32f2f;
    }
  }

  &:last-child {
    background-color: #4caf50;
    color: white;

    &:hover {
      background-color: #388e3c;
    }
  }
`;

const DeleteUserPopup = ({ showModal, closeModal, onDelete }) => {
  const { t } = useTranslation();

  // Nếu showModal là false, không render gì (không hiển thị popup)
  if (!showModal) return null;

  return (
    <Overlay>
      <PopupContainer>
        <Title>{t("deleteExperimentPopup.title")}</Title>
        <Message>{t("deleteExperimentPopup.confirmDelete")}</Message>

        <ButtonWrapper>
          {/* Button to cancel */}
          <Button onClick={closeModal}>{t("deletePopup.cancel")}</Button>

          {/* Button to confirm deletion */}
          <Button onClick={onDelete}>{t("deletePopup.delete")}</Button>
        </ButtonWrapper>
      </PopupContainer>
    </Overlay>
  );
};

export default DeleteUserPopup;
